const e=[{Claim:"Three age divisions: Junior (5 years old by 1 July and not over 12 by 31 July of the competition year), Youth (13 by 1 July and not over 18 by 31 July) and Adult (19 or older). A multi-member act enters the division of its average age. The template models solo acts and group acts as separate groups in each division: Junior 5-12, Youth 13-18, Adult 19-99.",SourceType:"Primary - the event's own rules document",Source:"K-Days Talent Search Rules and Regulations 2023 (Explore Edmonton)",Url:"https://assets-global.website-files.com/622a8f685d728511ae53ced4/63fe4b8ef499006affe45024_Talent%20Search%20Rules%20and%20Regulations%202023.pdf"},{Claim:"Acts may be vocal, instrumental, dance or variety (a mix of those), and an act may not run longer than 4 minutes 30 seconds, timed from the first sound or movement including introductions and tags. The rules rank acts by division and not by category, so the template has one item, Talent Act, entered by every act; the act type is a registration detail.",SourceType:"Primary - the event's own rules document",Source:"K-Days Talent Search Rules and Regulations 2023 (Explore Edmonton)",Url:"https://assets-global.website-files.com/622a8f685d728511ae53ced4/63fe4b8ef499006affe45024_Talent%20Search%20Rules%20and%20Regulations%202023.pdf"},{Claim:"Scoring as printed for semi-final performances: 60 percent technique and 40 percent showmanship, a total of 100. The template installs these two criteria. In the final the printed split is 60 technique, 30 showmanship and 10 for a 10-minute impromptu interview session; because a template carries one criteria set per item, the final's split is documented here and in the registration content only.",SourceType:"Primary - the event's own rules document",Source:"K-Days Talent Search Rules and Regulations 2023 (Explore Edmonton)",Url:"https://assets-global.website-files.com/622a8f685d728511ae53ced4/63fe4b8ef499006affe45024_Talent%20Search%20Rules%20and%20Regulations%202023.pdf"},{Claim:"Progression as printed: at least twelve winners per division move from video and open auditions to the semi-finals; three winners and one wild card per division advance to the final, giving 12 acts in the final. No marks, ranks or points for placings are printed, so none are installed.",SourceType:"Primary - the event's own rules document",Source:"K-Days Talent Search Rules and Regulations 2023 (Explore Edmonton)",Url:"https://assets-global.website-files.com/622a8f685d728511ae53ced4/63fe4b8ef499006affe45024_Talent%20Search%20Rules%20and%20Regulations%202023.pdf"},{Claim:"Rules the platform has no field for are left out on purpose: Alberta residency, amateur status definition, maximum group size, the three-person accompaniment limit, the penalty for acts over time at semi-final and final, music and lyrics submission by email, the ban on live animals, knives, fire and pyrotechnics, the 60-minute early arrival rule, the video audition rules and the prize-winner appearance commitments. They are kept in the registration content.",SourceType:"Scope note - rules with no matching field",Source:"K-Days Talent Search Rules and Regulations 2023 (Explore Edmonton)",Url:"https://assets-global.website-files.com/622a8f685d728511ae53ced4/63fe4b8ef499006affe45024_Talent%20Search%20Rules%20and%20Regulations%202023.pdf"},{Claim:"The printed maximum group sizes are inconsistent: Junior nine (9), Youth 'eight (9)' and Adult 'six (9)', where the word and the figure disagree. Group size is not a template field, so it is not modelled; a coordinator should confirm the limits with the organiser.",SourceType:"Scope note - source inconsistency",Source:"K-Days Talent Search Rules and Regulations 2023 (Explore Edmonton)",Url:"https://assets-global.website-files.com/622a8f685d728511ae53ced4/63fe4b8ef499006affe45024_Talent%20Search%20Rules%20and%20Regulations%202023.pdf"}],t="Built from the K-Days Talent Search Rules and Regulations 2023 (Explore Edmonton, Alberta, Canada). Ages follow the printed Junior 5-12, Youth 13-18 and Adult 19+ divisions, split into solo and group groups so each group has a real participant type; the printed age tests use 1 and 31 July dates that the platform cannot hold, so a coordinator should check dates of birth against the printed rule. One item (Talent Act) covers vocal, instrumental, dance and variety acts because the rules rank by division and not by act category. Judging uses the printed 60/40 technique and showmanship split used for semi-finals; the final's 60/30/10 split with an interview is documented only. No ranks, grades or points are printed. Group size limits are printed inconsistently and are not modelled. The document mixes 2022 and 2023 dates (open audition deadline printed as 25 May 2022, video deadline as 9 June 2023) and its numbering skips rule 15.",a=[{GroupName:"Junior Solo",AgeFrom:5,AgeTo:12,ParticipantTypeSetting:"Individual",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/primary.webp"},{GroupName:"Youth Solo",AgeFrom:13,AgeTo:18,ParticipantTypeSetting:"Individual",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/teen.webp"},{GroupName:"Adult Solo",AgeFrom:19,AgeTo:99,ParticipantTypeSetting:"Individual",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/adult.webp"},{GroupName:"Junior Group",AgeFrom:5,AgeTo:12,ParticipantTypeSetting:"Team",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/team-open.webp"},{GroupName:"Youth Group",AgeFrom:13,AgeTo:18,ParticipantTypeSetting:"Team",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/team-open.webp"},{GroupName:"Adult Group",AgeFrom:19,AgeTo:99,ParticipantTypeSetting:"Team",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/team-open.webp"}],i=[{CompetitionItem:0,Title:"Talent Act",Category:109,CategoryCategoryName:"Others",ScoreLabel:1,ScoreLabelLabel:"Marks",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/kids-talent-contest.webp",TimeCalculation:"TotalTime"}],n=[{CompetitionItem:0,CompetitionItemTitle:"Talent Act",Group:0,GroupGroupName:"Junior Solo",ParticipantType:1,ParticipantTypeTitle:"Individual",Gender:3,GenderGenderTitle:"Both",Language:4,LanguageLanguageName:"Any/NA",Fees:0,MaximumMinutes:4,MaximumScore:100,MaximumSeconds:30,WarningMinute:0,WarningSecond:0,Order:1,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/kids-talent-contest.webp"},{CompetitionItem:0,CompetitionItemTitle:"Talent Act",Group:0,GroupGroupName:"Youth Solo",ParticipantType:1,ParticipantTypeTitle:"Individual",Gender:3,GenderGenderTitle:"Both",Language:4,LanguageLanguageName:"Any/NA",Fees:0,MaximumMinutes:4,MaximumScore:100,MaximumSeconds:30,WarningMinute:0,WarningSecond:0,Order:2,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/kids-talent-contest.webp"},{CompetitionItem:0,CompetitionItemTitle:"Talent Act",Group:0,GroupGroupName:"Adult Solo",ParticipantType:1,ParticipantTypeTitle:"Individual",Gender:3,GenderGenderTitle:"Both",Language:4,LanguageLanguageName:"Any/NA",Fees:0,MaximumMinutes:4,MaximumScore:100,MaximumSeconds:30,WarningMinute:0,WarningSecond:0,Order:3,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/kids-talent-contest.webp"},{CompetitionItem:0,CompetitionItemTitle:"Talent Act",Group:0,GroupGroupName:"Junior Group",ParticipantType:2,ParticipantTypeTitle:"Team",Gender:3,GenderGenderTitle:"Both",Language:4,LanguageLanguageName:"Any/NA",Fees:0,MaximumMinutes:4,MaximumScore:100,MaximumSeconds:30,WarningMinute:0,WarningSecond:0,Order:4,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/kids-talent-contest.webp"},{CompetitionItem:0,CompetitionItemTitle:"Talent Act",Group:0,GroupGroupName:"Youth Group",ParticipantType:2,ParticipantTypeTitle:"Team",Gender:3,GenderGenderTitle:"Both",Language:4,LanguageLanguageName:"Any/NA",Fees:0,MaximumMinutes:4,MaximumScore:100,MaximumSeconds:30,WarningMinute:0,WarningSecond:0,Order:5,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/kids-talent-contest.webp"},{CompetitionItem:0,CompetitionItemTitle:"Talent Act",Group:0,GroupGroupName:"Adult Group",ParticipantType:2,ParticipantTypeTitle:"Team",Gender:3,GenderGenderTitle:"Both",Language:4,LanguageLanguageName:"Any/NA",Fees:0,MaximumMinutes:4,MaximumScore:100,MaximumSeconds:30,WarningMinute:0,WarningSecond:0,Order:6,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/kids-talent-contest.webp"}],o=[{CriteriaName:"Technique",SecondValue:"60",Order:1,CompetitionItemTitle:"Talent Act",GroupGroupName:"",ParticipantTypeTitle:""},{CriteriaName:"Showmanship",SecondValue:"40",Order:2,CompetitionItemTitle:"Talent Act",GroupGroupName:"",ParticipantTypeTitle:""}],r={Evidence:e,MaintenanceNote:t,AgeWiseGroups:a,CompetitionItems:i,CompetitionsAssignedToGroup:n,JudgesCriteria:o};export{a as AgeWiseGroups,i as CompetitionItems,n as CompetitionsAssignedToGroup,e as Evidence,o as JudgesCriteria,t as MaintenanceNote,r as default};
